#include <bits/stdc++.h>
using namespace std;

vector<double> crossSimple(long x, long y, long r, long tx, long ty, long tr) {
    long long d2 = (tx - x) * (tx - x) + (ty - y) * (ty - y);
    long long r_sum = r + tr;
    long long r_diff = abs(r - tr);
    if (d2 < r_diff * r_diff || d2 > r_sum * r_sum) {
        return {};
    }
    double base = atan2(ty - y, tx - x);
    double cos_value = (double)(d2 + r * r - tr * tr) / (2.0 * sqrt((double)d2) * r);
    if (cos_value > 1.0) cos_value = 1.0;
    if (cos_value < -1.0) cos_value = -1.0;
    double wing = acos(cos_value);
    double inf = base - wing;
    double sup = base + wing;
    return {inf, sup};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<array<long, 3>> co(n);
    for (int i = 0; i < n; i++) {
        cin >> co[i][0] >> co[i][1] >> co[i][2];
    }
    vector<double> nodes;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            vector<double> ts = crossSimple(co[i][0], co[i][1], co[i][2], co[j][0], co[j][1], co[j][2]);
            for (double t : ts) {
                nodes.push_back(co[i][0] + co[i][2] * cos(t));
                nodes.push_back(co[i][1] + co[i][2] * sin(t));
            }
        }
    }
    // Remove duplicates
    vector<pair<double, double>> unique_nodes;
    for (size_t i = 0; i + 1 < nodes.size(); i += 2) {
        bool found = false;
        for (auto &p : unique_nodes) {
            if (abs(p.first - nodes[i]) < 1e-12 && abs(p.second - nodes[i + 1]) < 1e-12) {
                found = true;
                break;
            }
        }
        if (!found) {
            unique_nodes.emplace_back(nodes[i], nodes[i + 1]);
        }
    }
    int p = (int)unique_nodes.size();
    int q = 0;
    vector<pair<double, double>> filtered_nodes;
    for (int i = 0; i < p; i++) {
        bool skip = false;
        for (int j = i + 1; j < p; j++) {
            double dist = (unique_nodes[i].first - unique_nodes[j].first) * (unique_nodes[i].first - unique_nodes[j].first) +
                          (unique_nodes[i].second - unique_nodes[j].second) * (unique_nodes[i].second - unique_nodes[j].second);
            if (dist < 1e-12) {
                skip = true;
                break;
            }
        }
        if (!skip) {
            filtered_nodes.push_back(unique_nodes[i]);
            q++;
        }
    }
    int nnodes = q;
    int ne = 0;
    int con = 1;
    for (int j = 0; j < n; j++) {
        int e = 0;
        for (int i = 0; i < q; i++) {
            double dist = (filtered_nodes[i].first - co[j][0]) * (filtered_nodes[i].first - co[j][0]) +
                          (filtered_nodes[i].second - co[j][1]) * (filtered_nodes[i].second - co[j][1]);
            if (abs(dist - co[j][2] * co[j][2]) < 1e-12) {
                e++;
            }
        }
        if (e == 0) con++;
        ne += e;
    }
    if (con > n) con = n;
    cout << (ne - nnodes + con + 1) << "\n";
    return 0;
}

